 "sync/atomic"
 "time"

 _ "github.com/go-sql-driver/mysql"
 "github.com/jmoiron/sqlx"
 "golang.org/x/net/dns/dnsmessage"
)

const zone="u.isucon.dev."
const updateToken="isupipe-authoritative-zone-update"
type zoneData struct {A map[string][4]byte; Known map[string]bool}
var current atomic.Pointer[zoneData]
var updateMu sync.Mutex
var store *sqlx.DB
var queries atomic.Uint64
var found atomic.Uint64
func loadZone() error {
 var rows []struct{Name string `db:"name"`;Type string `db:"type"`;Content string `db:"content"`}
 if err:=store.Select(&rows,"SELECT name,type,content FROM records WHERE disabled=0");err!=nil{return err}
 z:=&zoneData{A:map[string][4]byte{},Known:map[string]bool{zone:true}}
 for _,r:=range rows {name:=strings.ToLower(strings.TrimSuffix(r.Name,"."))+".";z.Known[name]=true;if r.Type=="A" {ip:=net.ParseIP(r.Content).To4();if ip!=nil{z.A[name]=[4]byte{ip[0],ip[1],ip[2],ip[3]}}}}
 current.Store(z);return nil
}
func zoneSOA() dnsmessage.Resource {
 name,_:=dnsmessage.NewName(zone);ns,_:=dnsmessage.NewName("ns1."+zone);mbox,_:=dnsmessage.NewName("hostmaster."+zone)
 return dnsmessage.Resource{Header:dnsmessage.ResourceHeader{Name:name,Type:dnsmessage.TypeSOA,Class:dnsmessage.ClassINET,TTL:0},Body:&dnsmessage.SOAResource{NS:ns,MBox:mbox,Serial:0,Refresh:10800,Retry:3600,Expire:604800,MinTTL:0}}
}
func answer(packet []byte) ([]byte,error) {
 var request dnsmessage.Message
 if err:=request.Unpack(packet);err!=nil{return nil,err}
 if request.Header.Response||len(request.Questions)!=1{return nil,fmt.Errorf("invalid question")}
 q:=request.Questions[0];name:=strings.ToLower(q.Name.String())
 response:=dnsmessage.Message{Header:dnsmessage.Header{ID:request.Header.ID,Response:true,Authoritative:true,RecursionDesired:request.Header.RecursionDesired},Questions:request.Questions}
