type result struct {ID int64 `json:"id"`;Affected int64 `json:"affected"`}
type response struct {Results []result `json:"results"`;Error string `json:"error,omitempty"`}
var database *sql.DB
var queue=make(chan *request,8192)
var count,batches,queries,failures atomic.Uint64
var batchDelay=200*time.Microsecond
func execute(batch []*request) {
 tx,err:=database.Begin();if err!=nil{for _,r:=range batch{r.done<-response{Error:err.Error()}};return}
 replies:=make([]response,len(batch))
 for i,r:=range batch {
  replies[i].Results=make([]result,0,len(r.Queries))
  for _,q:=range r.Queries {
   args:=make([]interface{},len(q.Args))
   for k,a:=range q.Args {switch a.Kind{case "int":args[k]=a.Integer;case "bytes":args[k]=a.Bytes;case "ref":if a.Reference<0||a.Reference>=len(replies[i].Results){err=fmt.Errorf("invalid insert reference")}else{args[k]=replies[i].Results[a.Reference].ID};case "nil":args[k]=nil;default:args[k]=a.Text}}
