  }
  if err!=nil{break}
 }
 if err==nil{err=tx.Commit()}else{tx.Rollback()}
 if err!=nil {
  // A failing transaction must not make unrelated operations fail.
  if len(batch)>1{middle:=len(batch)/2;execute(batch[:middle]);execute(batch[middle:]);return}
  failures.Add(1);batch[0].done<-response{Error:err.Error()};return
 }
 batches.Add(1);count.Add(uint64(len(batch)));for i,r:=range batch{r.done<-replies[i]}
}
func worker(){for first:=range queue{
 batch:=[]*request{first};timer:=time.NewTimer(batchDelay)
 gather:for len(batch)<64{select{case r:=<-queue:batch=append(batch,r);case <-timer.C:break gather}}
 if !timer.Stop(){select{case <-timer.C:default:}}
 execute(batch)
}}
