	lifecycleMu.RLock()
	defer lifecycleMu.RUnlock()
	path := c.Path()
	method := c.Request().Method
	public := path == "/api/tag" || path == "/api/livestream/search" || path == "/api/user/:username/icon" || path == "/api/payment"
